// Extract subscription info from Gmail emails
const items = $input.all();
const subscriptions = [];

for (const item of items) {
  const subject = item.json.subject || '';
  const snippet = item.json.snippet || '';
  const from = item.json.from || '';
  const body = subject + ' ' + snippet;

  // Extract vendor name (from email sender)
  const vendorMatch = from.match(/([^<@]+)/);
  const vendor = vendorMatch ? vendorMatch[1].trim() : 'Unknown';

  // Extract amount (looking for $XX.XX or XX.XX)
  const amountMatch = body.match(/\$?(\d+\.\d{2})/);
  const cost = amountMatch ? parseFloat(amountMatch[1]) : 0;

  // Detect billing cycle
  let billing_cycle = 'monthly';
  if (body.toLowerCase().includes('annual') || body.toLowerCase().includes('yearly')) {
    billing_cycle = 'annual';
  }

  // Only add if we found a cost
  if (cost > 0) {
    subscriptions.push({
      name: vendor,
      cost: cost,
      billing_cycle: billing_cycle,
      category: 'unknown',
      source: 'gmail'
    });
  }
}

return subscriptions.map(sub => ({ json: sub }));

// Merge all subscription sources and deduplicate

// Get data from different sources
const manualSubs = $('Set Defaults').first().json.manual_subscriptions || [];
const gmailSubs = $('Parse Gmail Subscriptions').all().map(item => item.json) || [];
const sheetSubs = $input.all().map(item => {
  return {
    name: item.json.name,
    cost: parseFloat(item.json.cost) || 0,
    billing_cycle: item.json.billing_cycle || 'monthly',
    category: item.json.category || 'unknown',
    renewal_date: item.json.renewal_date,
    source: 'google_sheets'
  };
}).filter(sub => sub.name && sub.cost > 0);

// Get user_id
const userId = $('Set Defaults').first().json.user_id;

// Filter sheet subscriptions by user_id
const userSheetSubs = $input.all()
  .filter(item => item.json.user_id === userId)
  .map(item => ({
    name: item.json.name,
    cost: parseFloat(item.json.cost) || 0,
    billing_cycle: item.json.billing_cycle || 'monthly',
    category: item.json.category || 'unknown',
    renewal_date: item.json.renewal_date,
    source: 'google_sheets'
  }))
  .filter(sub => sub.name && sub.cost > 0);

// Combine all sources
const allSubs = [...manualSubs, ...gmailSubs, ...userSheetSubs];

// Normalize and deduplicate
const normalized = new Map();

for (const sub of allSubs) {
  // Normalize name (lowercase, remove special chars)
  const normalizedName = sub.name.toLowerCase().replace(/[^a-z0-9]/g, '');

  // Convert all to monthly cost for comparison
  let monthlyCost = sub.cost;
  if (sub.billing_cycle === 'annual' || sub.billing_cycle === 'yearly') {
    monthlyCost = sub.cost / 12;
  }

  // Keep the most detailed entry (prefer manual > sheets > gmail)
  if (!normalized.has(normalizedName) || 
      (sub.source === 'manual' || 
       (sub.source === 'google_sheets' && normalized.get(normalizedName).source === 'gmail'))) {
    normalized.set(normalizedName, {
      name: sub.name,
      cost: sub.cost,
      monthly_cost: parseFloat(monthlyCost.toFixed(2)),
      billing_cycle: sub.billing_cycle || 'monthly',
      category: sub.category || 'unknown',
      renewal_date: sub.renewal_date,
      source: sub.source || 'manual'
    });
  }
}

// Convert back to array
const uniqueSubs = Array.from(normalized.values());

// Add metadata
return uniqueSubs.map(sub => ({
  json: {
    ...sub,
    user_id: userId,
    timestamp: $('Set Defaults').first().json.timestamp
  }
}));

