// Parse LLM response and calculate savings
const item = $input.first();

try {
  // Get LLM response
  const llmResponse = item.json.choices?.[0]?.message?.content;

  if (!llmResponse) {
    throw new Error('No LLM response received');
  }

  // Parse JSON response
  const analysis = JSON.parse(llmResponse);

  // Get original subscription data
  const originalSub = $('Split Into Batches').first().json;

  // Find best alternative (highest savings with good feature match)
  let bestAlternative = null;
  let maxSavings = 0;

  if (analysis.alternatives && analysis.alternatives.length > 0) {
    for (const alt of analysis.alternatives) {
      // Prefer alternatives with >70% feature match and positive savings
      if (alt.feature_match_percent >= 70 && alt.savings_month > maxSavings) {
        maxSavings = alt.savings_month;
        bestAlternative = alt;
      }
    }

    // If no good match found, take the one with highest savings
    if (!bestAlternative) {
      bestAlternative = analysis.alternatives.reduce((best, alt) => 
        alt.savings_month > best.savings_month ? alt : best
      );
    }
  }

  // Calculate if switch is worth it
  const worthSwitching = bestAlternative && 
    (bestAlternative.savings_month >= 10 || bestAlternative.feature_match_percent >= 80);

  return {
    json: {
      user_id: originalSub.user_id,
      timestamp: originalSub.timestamp,
      subscription: originalSub.name,
      current_cost: originalSub.monthly_cost,
      billing_cycle: originalSub.billing_cycle,
      category: originalSub.category,
      best_alternative: bestAlternative?.name || 'No alternative found',
      alternative_cost: bestAlternative?.cost || originalSub.monthly_cost,
      savings_month: bestAlternative?.savings_month || 0,
      savings_year: bestAlternative?.savings_year || 0,
      feature_match_percent: bestAlternative?.feature_match_percent || 0,
      worth_switching: worthSwitching,
      recommendation: analysis.recommendation || 'No recommendation available',
      all_alternatives: analysis.alternatives || [],
      analysis_status: 'success'
    }
  };

} catch (error) {
  // Handle errors gracefully
  const originalSub = $('Split Into Batches').first().json;

  return {
    json: {
      user_id: originalSub.user_id,
      timestamp: originalSub.timestamp,
      subscription: originalSub.name,
      current_cost: originalSub.monthly_cost,
      billing_cycle: originalSub.billing_cycle,
      category: originalSub.category,
      best_alternative: 'Analysis failed',
      alternative_cost: originalSub.monthly_cost,
      savings_month: 0,
      savings_year: 0,
      feature_match_percent: 0,
      worth_switching: false,
      recommendation: 'LLM analysis failed: ' + error.message,
      all_alternatives: [],
      analysis_status: 'error',
      error: error.message
    }
  };
}

// Aggregate all results and calculate totals
const allResults = $input.all();

if (allResults.length === 0) {
  return {
    json: {
      status: 'error',
      message: 'No subscriptions to analyze',
      total_subscriptions: 0,
      total_monthly_cost: 0,
      total_monthly_savings: 0,
      total_yearly_savings: 0,
      subscriptions: []
    }
  };
}

// Calculate totals
const totalMonthlyCost = allResults.reduce((sum, item) => sum + (item.json.current_cost || 0), 0);
const totalMonthlySavings = allResults.reduce((sum, item) => sum + (item.json.savings_month || 0), 0);
const totalYearlySavings = allResults.reduce((sum, item) => sum + (item.json.savings_year || 0), 0);

// Calculate savings percentage
const savingsPercentage = totalMonthlyCost > 0 
  ? ((totalMonthlySavings / totalMonthlyCost) * 100).toFixed(1)
  : 0;

// Format subscriptions for response
const subscriptions = allResults.map(item => ({
  name: item.json.subscription,
  current_cost: parseFloat(item.json.current_cost.toFixed(2)),
  billing_cycle: item.json.billing_cycle,
  category: item.json.category,
  best_alternative: item.json.best_alternative,
  alternative_cost: parseFloat((item.json.alternative_cost || 0).toFixed(2)),
  savings_month: parseFloat((item.json.savings_month || 0).toFixed(2)),
  savings_year: parseFloat((item.json.savings_year || 0).toFixed(2)),
  feature_match_percent: item.json.feature_match_percent,
  worth_switching: item.json.worth_switching,
  recommendation: item.json.recommendation
}));

// Sort by savings (highest first)
subscriptions.sort((a, b) => b.savings_month - a.savings_month);

// Get user_id from first result
const userId = allResults[0].json.user_id;
const timestamp = allResults[0].json.timestamp;

return {
  json: {
    status: 'success',
    user_id: userId,
    timestamp: timestamp,
    total_subscriptions: allResults.length,
    total_monthly_cost: parseFloat(totalMonthlyCost.toFixed(2)),
    total_monthly_savings: parseFloat(totalMonthlySavings.toFixed(2)),
    total_yearly_savings: parseFloat(totalYearlySavings.toFixed(2)),
    savings_percentage: parseFloat(savingsPercentage),
    subscriptions: subscriptions,
    detailed_results: allResults.map(item => item.json)
  }
};

// Format final response
const data = $input.first().json;

// Create human-friendly summary
const summary = `
🎯 Subscription Optimization Report

📊 Analysis Summary:
- Total Subscriptions Analyzed: ${data.total_subscriptions}
- Current Monthly Cost: $${data.total_monthly_cost}
- Potential Monthly Savings: $${data.total_monthly_savings}
- Potential Yearly Savings: $${data.total_yearly_savings}
- Savings Percentage: ${data.savings_percentage}%

💡 Top Savings Opportunities:
${data.subscriptions.slice(0, 3).map((sub, i) => 
  `${i + 1}. ${sub.name} → ${sub.best_alternative}\n   Save: $${sub.savings_month}/month ($${sub.savings_year}/year)\n   Feature Match: ${sub.feature_match_percent}%`
).join('\n\n')}

✅ Recommendations:
${data.subscriptions.filter(s => s.worth_switching).length} subscriptions worth switching
${data.subscriptions.filter(s => !s.worth_switching).length} subscriptions to keep
`;

return {
  json: {
    ...data,
    summary: summary.trim()
  }
};

// Handle errors - return to webhook
return {
  json: {
    status: 'error',
    error: $input.first().json.error?.message || 'An error occurred',
    message: 'Workflow encountered an error. Check logs for details.',
    timestamp: new Date().toISOString()
  }
};
